import{_ as e,a as d,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Catalog Attribute Families — Datagrid Listing (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-families-list","title":"List Attribute Families (Datagrid)","description":"Cursor-paginated query returning the flat attribute family list — the GraphQL equivalent of the admin Catalog → Attribute Families datagrid. Supports filtering by code and name. Returns only 3 fields per node (id, code, name) because the underlying table carries no timestamps.","query":"query AdminAttributeFamilies(\\n  $first: Int\\n  $after: String\\n  $code: String\\n  $name: String\\n  $sort: String\\n  $order: String\\n) {\\n  adminAttributeFamilies(\\n    first: $first\\n    after: $after\\n    code: $code\\n    name: $name\\n    sort: $sort\\n    order: $order\\n  ) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        code\\n        name\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      hasPreviousPage\\n      endCursor\\n      startCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"sort\\": \\"id\\",\\n  \\"order\\": \\"desc\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminAttributeFamilies\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/families/3\\",\\n            \\"_id\\": 3,\\n            \\"code\\": \\"apparel\\",\\n            \\"name\\": \\"Apparel\\"\\n          }\\n        },\\n        {\\n          \\"cursor\\": \\"MQ==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/catalog/families/1\\",\\n            \\"_id\\": 1,\\n            \\"code\\": \\"default\\",\\n            \\"name\\": \\"Default\\"\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"hasPreviousPage\\": false,\\n        \\"endCursor\\": \\"MQ==\\",\\n        \\"startCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 2\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/families/families-listing.md","filePath":"api/graphql-api/admin/catalog/families/families-listing.md","lastUpdated":1787290888000}'),r={name:"api/graphql-api/admin/catalog/families/families-listing.md"};function i(n,t,c,s,l,u){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="catalog-attribute-families-—-datagrid-listing-graphql" tabindex="-1">Catalog Attribute Families — Datagrid Listing (GraphQL) <a class="header-anchor" href="#catalog-attribute-families-—-datagrid-listing-graphql" aria-label="Permalink to &quot;Catalog Attribute Families — Datagrid Listing (GraphQL)&quot;">​</a></h1><p>Cursor-paginated GraphQL query that mirrors the Bagisto admin <strong>Catalog → Attribute Families</strong> datagrid. Returns the flat family list with filtering, sorting, and cursor pagination.</p><p>For how a family&#39;s attribute groups and attributes are structured, and the delete guards, see the <a href="/api/graphql-api/admin/catalog/families/">Attribute Families overview</a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Pagination</th></tr></thead><tbody><tr><td><code>adminAttributeFamilies</code></td><td>Query</td><td>Cursor (<code>first</code> / <code>after</code>)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>Number of items per page (default <code>10</code>, max <code>50</code>)</td><td><code>10</code></td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.endCursor</code> for keyset pagination</td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>last</code></td><td><code>Int</code></td><td>Page size when paging backwards</td><td><code>10</code></td></tr><tr><td><code>before</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.startCursor</code></td><td><code>&quot;MA==&quot;</code></td></tr><tr><td><code>id</code></td><td><code>String</code></td><td>Filter by family ID — single integer or comma-separated list (e.g. <code>&quot;1&quot;</code> or <code>&quot;1,2&quot;</code>)</td><td><code>&quot;1&quot;</code></td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Partial family code match (SQL <code>LIKE %value%</code>)</td><td><code>&quot;default&quot;</code></td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Partial family name match (SQL <code>LIKE %value%</code>)</td><td><code>&quot;Apparel&quot;</code></td></tr><tr><td><code>sort</code></td><td><code>String</code></td><td>Column to sort by (see Sorting section below)</td><td><code>&quot;id&quot;</code></td></tr><tr><td><code>order</code></td><td><code>String</code></td><td>Sort direction: <code>&quot;asc&quot;</code> or <code>&quot;desc&quot;</code> (default <code>&quot;desc&quot;</code>)</td><td><code>&quot;desc&quot;</code></td></tr></tbody></table><p>Every filter is a first-class GraphQL argument — pass them alongside <code>first</code> and <code>after</code>, not inside a nested filter object. Filters combine with AND, so each one narrows the result.</p><h2 id="node-fields" tabindex="-1">Node Fields <a class="header-anchor" href="#node-fields" aria-label="Permalink to &quot;Node Fields&quot;">​</a></h2><p>Each <code>edges[].node</code> object contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>API Platform IRI (e.g. <code>/api/admin/catalog/families/1</code>)</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Raw family ID</td></tr><tr><td><code>code</code></td><td><code>String</code></td><td>Family code (e.g. <code>default</code>, <code>apparel</code>)</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Family display name (e.g. <code>Default</code>, <code>Apparel</code>)</td></tr></tbody></table><h2 id="fields-that-are-not-here" tabindex="-1">Fields That Are Not Here <a class="header-anchor" href="#fields-that-are-not-here" aria-label="Permalink to &quot;Fields That Are Not Here&quot;">​</a></h2><p>The listing is deliberately three fields. Families carry <strong>no timestamps at all</strong> — there is no <code>createdAt</code> or <code>updatedAt</code> on this resource, unlike every other admin listing — so you cannot sort or filter by date here.</p><p><code>attributeGroups</code> resolves only on <a href="/api/graphql-api/admin/catalog/families/families-detail.html"><code>adminAttributeFamily(id:)</code></a>; selecting it on the listing returns <code>null</code>.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Pass <code>sort</code> with the column name and <code>order</code> for direction.</p><p><strong>Sortable columns:</strong></p><table tabindex="0"><thead><tr><th><code>sort</code> value</th><th>Sorts by</th></tr></thead><tbody><tr><td><code>id</code></td><td>Family ID (default)</td></tr><tr><td><code>code</code></td><td>Family code</td></tr><tr><td><code>name</code></td><td>Family display name</td></tr></tbody></table><h2 id="cursor-pagination" tabindex="-1">Cursor Pagination <a class="header-anchor" href="#cursor-pagination" aria-label="Permalink to &quot;Cursor Pagination&quot;">​</a></h2><ul><li><code>first</code> controls the page size (default <code>10</code>, max <code>50</code>).</li><li>To fetch the next page, pass the <code>pageInfo.endCursor</code> value as <code>after</code> in the next request.</li><li><code>totalCount</code> reflects the full count of matching families across all pages.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Same provider as the REST endpoint</strong> — <code>AdminAttributeFamilyCollectionProvider</code> serves both transports with identical filter and sort semantics.</li><li><strong>Only 3 node fields are available.</strong> The listing is intentionally slim — <code>id</code>, <code>_id</code>, <code>code</code>, <code>name</code>. No timestamps exist on the table and attribute groups are not embedded in the listing.</li><li><strong><code>extraArgs</code> declares custom arguments.</strong> The filter/sort arguments are not part of the standard API Platform GraphQL schema for <code>QueryCollection</code> — they are explicitly declared via <code>extraArgs</code> on the operation. Pass them at the top level of the query, alongside <code>first</code> and <code>after</code>.</li><li><strong><code>attributeGroups</code> is not a field in this query.</strong> It is only populated by the item query <code>adminAttributeFamily(id: ID!)</code>. Requesting <code>attributeGroups</code> in the collection query will cause a GraphQL schema error.</li></ul>',22)]))}const g=e(r,[["render",i]]);export{m as __pageData,g as default};
